Object.keys(LNK_EXTRA_TRANSLATIONS).forEach(lang=>Object.assign(LNK_TRANSLATIONS[lang],LNK_EXTRA_TRANSLATIONS[lang]));
let activeLanguage='en';
function applyLanguage(lang){
 lang=Object.prototype.hasOwnProperty.call(LNK_TRANSLATIONS,lang)?lang:'en';
 activeLanguage=lang;
 const t=LNK_TRANSLATIONS[lang];
 document.documentElement.lang=lang;
 document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(t[key])el.textContent=t[key];});
 document.querySelectorAll('[data-i18n-aria]').forEach(el=>{const key=el.dataset.i18nAria;if(t[key])el.setAttribute('aria-label',t[key]);});
 // Keep the full business name in the home link's accessible label in every language.
 const brandLink=document.querySelector('.brand');
 if(brandLink)brandLink.setAttribute('aria-label','LNK DIGITAL · '+t.homeLabel);
 document.getElementById('heroTitle').innerHTML=t.heroTitle;
 document.getElementById('contactTitle').innerHTML=t.contactTitle;
 document.getElementById('languageSelect').value=lang;
 const menu=document.getElementById('menuBtn');
 menu.setAttribute('aria-label',t[menu.getAttribute('aria-expanded')==='true'?'menuClose':'menuOpen']);
 const title=lang==='en'?'LNK DIGITAL | Premium Web Design, Development & SEO':'LNK DIGITAL | '+t.x32;
 document.title=title;
 document.querySelector('meta[name="description"]').content=t.heroLead;
 document.querySelector('meta[property="og:title"]').content=title;
 document.querySelector('meta[property="og:description"]').content=t.heroLead;
 document.querySelectorAll('a[href^="https://wa.me/"]').forEach(link=>{
  const contact=Boolean(link.closest('#contact'));
  link.href='https://wa.me/38631244612?text='+encodeURIComponent(t.whatsappHello+(contact?' '+t.whatsappBusiness+' ':''));
 });
 try{localStorage.setItem('lnk-language',lang)}catch(e){}
}
const languageSelect=document.getElementById('languageSelect');
languageSelect.addEventListener('change',e=>applyLanguage(e.target.value));
let saved=(navigator.language||'en').slice(0,2).toLowerCase();
try{saved=localStorage.getItem('lnk-language')||saved}catch(e){}
const requestedLocale=new URLSearchParams(location.search).get('lang');
if(requestedLocale&&Object.prototype.hasOwnProperty.call(LNK_TRANSLATIONS,requestedLocale))saved=requestedLocale;
applyLanguage(saved);


const btn=document.getElementById('menuBtn'),nav=document.getElementById('mobileNav');
btn.setAttribute('aria-controls','mobileNav');
function setMenu(open){
 nav.classList.toggle('open',open);
 btn.setAttribute('aria-expanded',String(open));
 btn.setAttribute('aria-label',LNK_TRANSLATIONS[activeLanguage][open?'menuClose':'menuOpen']);
 btn.textContent=open?'×':'☰';
}
btn.addEventListener('click',()=>setMenu(btn.getAttribute('aria-expanded')!=='true'));
document.addEventListener('click',e=>{if(!e.target.closest('.site-header'))setMenu(false);});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&btn.getAttribute('aria-expanded')==='true'){setMenu(false);btn.focus();}});

